const doctor_id = Number($json.doctor_id);
const appointment_date = String($json.appointment_date || "").trim();

if (!doctor_id || !appointment_date) {
  return [
    {
      json: {
        valid: false,
        error: "doctor_id and appointment_date are required."
      }
    }
  ];
}

const match = appointment_date.match(/^(\d{4})-(\d{2})-(\d{2})$/);

if (!match) {
  return [
    {
      json: {
        valid: false,
        error: "Invalid appointment_date. Use YYYY-MM-DD format."
      }
    }
  ];
}

const year = Number(match[1]);
const month = Number(match[2]);
const day = Number(match[3]);

const date = new Date(Date.UTC(year, month - 1, day));

const days = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday"
];

const day_of_week = days[date.getUTCDay()];

return [
  {
    json: {
      valid: true,
      doctor_id,
      appointment_date,
      day_of_week
    }
  }
];

const row = items[0]?.json;

if (!row) {
  return [
    {
      json: {
        available: false,
        reason: "Doctor not found or inactive.",
        message: "Doctor not found or inactive."
      }
    }
  ];
}

if (!row.day_of_week || row.is_available === 0 || row.is_available === false) {
  return [
    {
      json: {
        available: false,
        doctor_id: row.doctor_id,
        doctor_name: row.doctor_name,
        department: row.department,
        appointment_date: $node["Prepare Availability Input"].json.appointment_date,
        day_of_week: $node["Prepare Availability Input"].json.day_of_week,
        reason: "Doctor is not available on this date.",
        message: `${row.doctor_name} is not available on this date.`
      }
    }
  ];
}

return [
  {
    json: {
      available: true,
      doctor_id: row.doctor_id,
      doctor_name: row.doctor_name,
      department: row.department,
      specialization: row.specialization,
      appointment_date: $node["Prepare Availability Input"].json.appointment_date,
      day_of_week: row.day_of_week,
      consultation_duration: row.consultation_duration,
      available_from: row.start_time,
      available_to: row.end_time,
      message: `${row.doctor_name} is available from ${row.start_time} to ${row.end_time}.`
    }
  }
];
